import{_ as l,l as o,o as e,c as n,v as t,p as s,x as i,d as h,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Rothschild–Stiglitz 崩溃","description":"","frontmatter":{"title":"Rothschild–Stiglitz 崩溃","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rs-unraveling.md","filePath":"econ/rs-unraveling.md","lastUpdated":1789023840000}'),c={name:"econ/rs-unraveling.md"};function p(A,a,u,m,_,B){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="rothschild–stiglitz-崩溃" tabindex="-1">Rothschild–Stiglitz 崩溃 <a class="header-anchor" href="#rothschild–stiglitz-崩溃" aria-label="Permalink to &quot;Rothschild–Stiglitz 崩溃&quot;">​</a></h1><div class="epigraph"><p>竞争性保险筛选下，混同不是均衡；分离候选也可以被新合同挖走。自由进入加上逆向选择，均衡可以空。</p><footer>—— Rothschild and Stiglitz, Equilibrium in Competitive Insurance Markets, QJE, 1976</footer></div><p><a href="/econ/screening-rent">上一课</a>在单个委托人下写出菜单、信息租金与「扭曲低类型」。缺口是把委托人换成自由进入的保险公司：利润被削到零之后，那份刚好分离的菜单未必站得住。本课钉竞争筛选的存在性崩溃，不重写垄断下租金公式，也不把事故概率写成隐藏努力。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两类型风险，不知情的保险公司先出保单，知情投保人自选。竞争：自由进入，被选中的保单零利润，且不存在新保单能在现有保单旁边赚正利润。筛选课的垄断解靠利润（或福利）目标压住菜单；这里任何人都可以再丢一张合同进场。</p><p>混同先垮：平均精算的全保险（或任何混同点）上，总可以画一张对低风险更甜、对高风险不够甜的偏离保单，把低风险撇走，留下高风险让原保单亏损。分离候选：高风险拿其完全信息全保险，低风险拿部分保险，IC 刚好绑住高风险。零利润要求各保单按自身类型定价。但若低风险足够多，再丢一张接近混同、略亏高风险但大赚低风险的合同，可以把低风险再挖走——分离也垮。于是均衡空。</p><h3 id="崩溃不是柠檬的切断" tabindex="-1">崩溃不是柠檬的切断 <a class="header-anchor" href="#崩溃不是柠檬的切断" aria-label="Permalink to &quot;崩溃不是柠檬的切断&quot;">​</a></h3><p>柠檬只有一个价格，好车退出。RS 有数量（保障额度）可以分离，按理比柠檬多一件工具。崩溃来自第三件东西：自由进入。工具够分离，却不够同时挡住撇脂与零利润。垄断委托人不会自己撇自己的油，所以筛选课有解。</p><p><span class="marginnote">Wilson 预期均衡、Riley 反应均衡、Miyazaki–Wilson 交叉补贴，后来用不同的「别人会怎么反应」恢复存在性。1976 年的定义是静态「新合同赚正利润」，结论以不存在闻名。本课钉这一定义，不把后继概念写进定理。</span></p><p>高风险足够多时，挖走低风险的那张混同式合同自己会亏，分离可以站住。 崩溃因此是参数区域：低风险太多，撇脂太甜。 存在性空不是保险市场经验上消失；强制投保、社区定价是制度回应。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：两类型、单交叉无差异曲线、风险中性公司、自由进入。先排除混同（撇脂偏离），再写分离候选的零利润 + IC，再检查是否存在有利可图的「再混同」偏离。低风险比例过阈值则分离被破。</p>',12)),(e(),s(E,null,{default:i(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E5%9E%84%E6%96%AD%E7%AD%9B%E9%80%89%EF%BC%9A%E6%9C%89%E8%A7%A3%22%5D%20--%3E%20COMP%5B%22%E8%87%AA%E7%94%B1%E8%BF%9B%E5%85%A5%22%5D%0A%20%20POOL%5B%22%E6%B7%B7%E5%90%8C%22%5D%20--%3E%20SKIM%5B%22%E6%92%87%E8%84%82%EF%BC%9A%E6%B7%B7%E5%90%8C%E9%9D%9E%E5%9D%87%E8%A1%A1%22%5D%0A%20%20SEP%5B%22%E5%88%86%E7%A6%BB%E5%80%99%E9%80%89%22%5D%20--%3E%20CROSS%5B%22%E4%BD%8E%E9%A3%8E%E9%99%A9%E5%A4%9A%E5%88%99%E5%86%8D%E8%A2%AB%E6%8C%96%E8%B5%B0%22%5D%0A%20%20CROSS%20--%3E%20EMPTY%5B%22%E5%9D%87%E8%A1%A1%E5%8F%AF%E4%BB%A5%E7%A9%BA%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>竞争把交叉补贴定为攻击对象：任何「低风险补贴高风险」的包，都可以被只面向低风险的包拆开。分离把补贴拆掉了，却给低风险留下未吃尽的剩余（相对于混同全保险）。人一多，这份剩余大到值得再开一张接近混同的单，分离被自己的竞争逻辑吃掉。筛选课的租金在垄断那里是委托人付给高类型的；竞争里租金被进入拆光，连配置一起拆空。</p><p>这与<a href="/econ/ge-existence">存在性</a>的对照：Arrow–Debreu 的商品是给定的，价格在单纯形上；这里策略是合同，偏离是创造新商品。凸性帮不上。显示原理仍适用，但「设计者」不是一个人，而是任何一家可以进入的公司。柠檬只有价格切断；RS 有保障数量，本可以分离，崩溃来自进入把交叉补贴与未吃尽的低风险剩余都变成攻击面。垄断委托人不会对自己撇油，所以<a href="/econ/screening-rent">筛选</a>有解、竞争可以无解。</p><p>低风险足够多，未吃尽的剩余才大到值得再开接近混同的单；高风险多时分离可以站住。 崩溃因此是参数区域，不是保险市场经验上消失。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把「均衡空」读成道德风险：类型是事故概率，签约前已存在。隐藏努力是 Holmström 一线。也不要重算一遍 Mussa–Rosen 的数量扭曲：垄断下那份扭曲在竞争里先被零利润改写，再被进入打掉。附录对照原文细节见 Rothschild–Stiglitz 附录课；主干只记崩溃机制。</p><p>后课默认：竞争出菜单可以没有均衡；要存在，须换均衡概念、限制进入，或回到垄断委托人。隐藏行动的合同竞争是另一棵树。</p><h3 id="强制混同是用存在性换效率" tabindex="-1">强制混同是用存在性换效率 <a class="header-anchor" href="#强制混同是用存在性换效率" aria-label="Permalink to &quot;强制混同是用存在性换效率&quot;">​</a></h3><p>社会保障、社区评级强迫低风险留在池里，撇脂被禁止，均衡回来，效率不必是分离有效。RS 把这一点写成政策含义：竞争在逆向选择下不是自动好事。Wilson 预期若成立，公司不敢出撇脂单，因为预见到剩下的全是高风险——那是另一均衡概念下的逐级退出，与柠檬顶部退出同构，对象换成保单。</p><p><span class="marginnote">筛选课已经警告「菜单竞争不必有均衡」。本课把那句警告收成定理：混同必垮，分离可空。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>竞争筛选：混同必被撇脂；分离在低风险多时也可被挖走。</li><li>自由进入把垄断筛选的解拆空，存在性可以失败。</li><li>这是隐藏类型 + 合同进入，不是隐藏努力。</li><li>强制混同、反应均衡是后继补丁，不是 1976 年定理内部的解。</li><li>出处：Rothschild and Stiglitz, <em>QJE</em> 1976。</li></ul>',12))])}const g=l(c,[["render",p]]);export{f as __pageData,g as default};
